// ---- Build 3 product dropdowns from actions.* lists
(function () {
  /**
   * Safely builds a dropdown's HTML and stores it in transforms via ZT.setTransformData.
   * @param {Object} opts
   * @param {Array}  opts.list             - Array of product items (ProductDisplayList)
   * @param {String} opts.transformAlias   - Name used to store HTML (e.g., "productOneDropdownHtml")
   * @param {String} opts.selectId         - <select> id (e.g., "productOneSelect")
   * @param {String} opts.dataAlias        - data-alias on <select> (e.g., "product_1")
   * @param {String} opts.labelText        - Label text for the dropdown
   * @param {String} [opts.preselectedId]  - ProductID to preselect (as string)
   */
  function buildDropdown({ list, transformAlias, selectId, fieldName, dataAlias, labelText, preselectedId = "" }) {
    try {
      if (!Array.isArray(list) || list.length === 0) {
        // ZT.log(`[${transformAlias}] No ProductDisplayList found.`);
        ZT.setTransformData(
          transformAlias,
          '<div class="zt-warning">No products available.</div>'
        );
        return;
      }

      // Sort alphabetically by DisplayName (case-insensitive)
      const products = [...list].sort((a, b) =>
        (a.DisplayName || "").localeCompare(b.DisplayName || "", undefined, { sensitivity: "base" })
      );


      const options = products.map(p => {
        const id = String(p.ProductID ?? "");
        const name = ZT.htmlEncode(p.DisplayName ?? `Product ${id}`);
        const provider = p.ProviderID ?? "";
        const selected = preselectedId && preselectedId === id ? " selected" : "";
        return `<option value="${id}" data-provider-id="${provider}"${selected}>${name}</option>`;
      }).join("");

      const html = `
        <div class="zt-form-group">
          <label for="${selectId}">${ZT.htmlEncode(labelText)}</label>
          <select id="${selectId}" name="${fieldName}" class="form-control zt-data" data-alias="${ZT.htmlEncode(dataAlias)}">
            <option value="">-- Select a product --</option>
            ${options}
          </select>
        </div>
      `;

      ZT.setTransformData(transformAlias, html);
      // ZT.log(`[${transformAlias}] Dropdown HTML generated.`);
    } catch (err) {
      // ZT.log(`[${transformAlias}] Error: ${err?.message || err}`);
      ZT.setTransformData(
        transformAlias,
        '<div class="zt-error">There was a problem building the product list.</div>'
      );
    }
  }

  // ----- Source lists from actions.* (same schema: .d.ProductDisplayList)
  const list1 = actions?.defaqto_loadproductdropdownlist_product_1?.d?.ProductDisplayList;
  const list2 = actions?.defaqto_loadproductdropdownlist_product_2?.d?.ProductDisplayList;
  const listBase = actions?.defaqto_loadproductdropdownlist_product?.d?.ProductDisplayList;

  // ----- Preselect previous choices (form data captured from the zt-data selects on node 1)
  const pre1 = String(ZT.getVariableValue("product_one_id", "") || "");
  const pre2 = String(ZT.getVariableValue("product_two_id", "") || "");
  const preBase = String(ZT.getVariableValue("product_id", "") || "");

  // ----- Build all three dropdowns
  buildDropdown({
    list: list1,
    transformAlias: "productOneDropdownHtml",
    selectId: "productOneSelect",
    fieldName: "product_one_id",
    dataAlias: "product_1",
    labelText: "Choose product #1",
    preselectedId: pre1
  });

  buildDropdown({
    list: list2,
    transformAlias: "productTwoDropdownHtml",
    selectId: "productTwoSelect",
    fieldName: "product_two_id",
    dataAlias: "product_2",
    labelText: "Choose product #2",
    preselectedId: pre2
  });

  buildDropdown({
    list: listBase,
    transformAlias: "productMainDropdownHtml",
    selectId: "productMainSelect",
    fieldName: "product_id",
    dataAlias: "product",
    labelText: "Choose product (First Central)",
    preselectedId: preBase
  });
})();

// Extract all QuestionIds from actions.defaqto_getquestionresponses and output as a comma-separated string
try {
  // Access Defaqto question data safely
  const questionsArray = actions?.defaqto_getquestionresponses?.d || [];

  // ZT.log("Starting extraction of QuestionIds from Defaqto responses...");

  // Check for valid array
  if (!Array.isArray(questionsArray) || questionsArray.length === 0) {
    // ZT.log("No question data found in actions.defaqto_getquestionresponses");
    ZT.setTransformData("defaqto_question_ids", "");
  } else {
    // Extract only the QuestionId values
    const questionIds = questionsArray.map(q => q.QuestionId);

    // Join them into a single comma-separated string
    const questionIdsString = questionIds.join(",");

    // Log and set to transform namespace
    // ZT.log(`Extracted ${questionIds.length} QuestionIds successfully.`);
    ZT.setTransformData("defaqto_question_ids", questionIdsString);
  }
} catch (err) {
  // ZT.log(`Error extracting QuestionIds: ${err.message}`);
  ZT.setTransformData("defaqto_question_ids", "");
}

