/**
 * Purpose:
 *   From actions.defaqto_loaddisplaysettings (payload shown in the prompt),
 *   find the three DropDownList entries by DefaultText and store their DropDownId
 *   into three transform variables:
 *     - dropdownIdYourProduct
 *     - dropdownIdProductOne
 *     - dropdownIdProductTwo
 *
 * Notes:
 *   - Uses ZT.setTransformData(...) to persist values for use in Content Nodes, etc.
 *   - Safe access with optional chaining and defensive checks.
 *   - If a target item isn't found, we set its transform to null and log a warning.
 */

(function () {
  // Helper: case-insensitive finder by DefaultText
  function findByDefaultText(list, target) {
    if (!Array.isArray(list)) return null;
    const wanted = String(target || "").trim().toLowerCase();
    return list.find(
      (item) => String(item?.DefaultText || "").trim().toLowerCase() === wanted
    ) || null;
  }

  // Pull the DropDownList array from actions
  const ddl =
    actions?.defaqto_loaddisplaysettings?.d?.DropDownList ??
    actions?.defaqto_loaddisplaysettings?.DropDownList ??
    [];

  // Locate each entry
  const yourProduct = findByDefaultText(ddl, "Your Product");
  const productOne  = findByDefaultText(ddl, "Product 1");
  const productTwo  = findByDefaultText(ddl, "Product 2");

  // Extract IDs (or null if not present)
  const yourProductId = yourProduct?.DropDownId ?? null;
  const productOneId  = productOne?.DropDownId ?? null;
  const productTwoId  = productTwo?.DropDownId ?? null;

  // Persist to transformations namespace
  ZT.setTransformData("dropdownIdYourProduct", yourProductId);
  ZT.setTransformData("dropdownIdProductOne",  productOneId);
  ZT.setTransformData("dropdownIdProductTwo",  productTwoId);

  // Optional: log for debugging
  // ZT.log(`[Defaqto LoadDisplaySettings] Found DropDownId(s): ` +
  //        `Your Product=${yourProductId}, Product 1=${productOneId}, Product 2=${productTwoId}`);

  // (Optional) also store the matched objects if you want to inspect later:
  // ZT.setTransformData("dropdownYourProductObj", yourProduct || null);
  // ZT.setTransformData("dropdownProductOneObj",  productOne  || null);
  // ZT.setTransformData("dropdownProductTwoObj",  productTwo  || null);
})();

