// JS Script Node (server side)

/**
 * Defaqto Comparison Table Builder + Star Rating Summary
 * ------------------------------------------------------
 * Produces:
 *   transforms.defaqtoComparisonTableHtml  -> comparison table HTML (EXCLUDES "Private Car Insurance Star Rating")
 *   transforms.defaqtoStarRatingHtml       -> NON-table block for "Private Car Insurance Star Rating"
 *
 * Also produces:
 *   transforms.defaqtoComparisonJson       -> pretty JSON string (LLM-friendly)
 *   transforms.defaqtoComparisonJsonObj    -> JSON object
 *
 * Usage in Content Node:
 *   ${transforms.defaqtoStarRatingHtml}
 *   ${transforms.defaqtoComparisonTableHtml}
 *   ${transforms.defaqtoComparisonJson}   (optional)
 */

// Keep your existing questions list reference
var questionsList = actions.defaqto_getquestionresponses;

/**
 * PART 1: TABLE BUILDER (with enhancements)
 * - Removes "Private Car Insurance Star Rating" from defaqtoComparisonTableHtml
 * - Creates defaqtoStarRatingHtml as a separate NON-table block
 */
(function () {
  // -------- Helpers --------------------------------------------------------

  const enc = (s) => ZT.htmlEncode(String(s ?? "").trim());
  const stripHtml = (s) => String(s ?? "").replace(/<[^>]*>/g, "").trim();

  const pullAnswer = (row) => {
    // Primary requirement: use DisplayText. Fallbacks help readability if DisplayText empty.
    const a = (row && row.DisplayText) ? String(row.DisplayText).trim() : "";
    if (a) return a;

    if (row && row.BrochureText && stripHtml(row.BrochureText)) {
      return stripHtml(row.BrochureText);
    }
    return ""; // intentionally blank
  };

  const toIndexByTitle = (arr) => {
    const idx = new Map();
    (arr || []).forEach((r) => {
      const key = r && r.QuestionTitle ? String(r.QuestionTitle).trim() : null;
      if (key && !idx.has(key)) idx.set(key, r);
    });
    return idx;
  };

  const hasVal = (v) => v !== undefined && v !== null && String(v).trim() !== "";

  // Interpret DisplayImageUrl signal (yes/no/maybe/off)
  const imageSignal = (url) => {
    const u = String(url ?? "").toLowerCase().trim();
    if (!u) return null;
    if (u.includes("/yes")) return "yes";
    if (u.includes("/no")) return "no";
    if (u.includes("/maybe")) return "maybe";
    if (u.includes("/off")) return "off";
    return null;
  };

  // --- Star-rating question title (single source of truth) -----------------
  const STAR_RATING_TITLE = "Private Car Insurance Star Rating";

  const isStarRatingTitle = (title) =>
    String(title ?? "").trim().toLowerCase() === STAR_RATING_TITLE.toLowerCase();

  // Render numeric rating ("5", "5 Star", etc.) as ★/☆ HTML + number
  const renderStarRatingHtml = (text) => {
    if (!text) return null;

    const raw = String(text).trim();
    const match = raw.match(/(\d+)/);
    if (!match) return null;

    let value = parseInt(match[1], 10);
    if (isNaN(value)) return null;

    // Clamp 1–5
    value = Math.max(1, Math.min(5, value));

    // Build five star elements: filled or empty
    const stars = [];
    for (let i = 1; i <= 5; i++) {
      const filled = i <= value;
      stars.push(
        `<span class="star-rating__star ${filled ? "is-filled" : "is-empty"}">★</span>`
      );
    }

    return `
      <span class="star-rating" aria-label="${enc(value)} out of 5 stars">
        ${stars.join("")}
        <span class="star-rating__number">(${enc(value)})</span>
      </span>
    `;
  };

  // -------- Help text index (QuestionId -> Help) ---------------------------

  const questionResponses = questionsList?.d || [];
  const helpByQuestionId = new Map();

  (questionResponses || []).forEach((qr) => {
    if (qr && typeof qr.QuestionId !== "undefined" && qr.QuestionId !== null) {
      helpByQuestionId.set(qr.QuestionId, qr.Help || "");
    }
  });

  const getHelpForRow = (rowMain, rowOne, rowTwo) => {
    // Prefer QuestionId from main, then product 1, then product 2
    const qId =
      (rowMain && rowMain.QuestionId) ||
      (rowOne && rowOne.QuestionId) ||
      (rowTwo && rowTwo.QuestionId) ||
      null;

    if (!qId) return "";
    return helpByQuestionId.get(qId) || "";
  };

  // -------- Variables & Names ---------------------------------------------

  // Product IDs (used to decide if a column has data)
  const productId = ZT.getVariableValue("product_id", null);
  const productOneId = ZT.getVariableValue("product_one_id", null);
  const productTwoId = ZT.getVariableValue("product_two_id", null);

  // Product Names (for column headers)
  const productName = ZT.getVariableValue("product_name", "Product");
  const productOneName = ZT.getVariableValue("product_one_name", "Product 1");
  const productTwoName = ZT.getVariableValue("product_two_name", "Product 2");

  // Column availability (must have an ID AND a payload to really compare)
  const colHasMain = hasVal(productId);
  const colHasOne = hasVal(productOneId);
  const colHasTwo = hasVal(productTwoId);

  // -------- Action Payloads ------------------------------------------------
  // Expecting the structure shown in your example (objects with a "d" array).
  const dataMain = actions?.defaqto_loadanswersbyquestionids?.d || [];
  const dataOne = actions?.defaqto_loadanswersbyquestionids_product_1?.d || [];
  const dataTwo = actions?.defaqto_loadanswersbyquestionids_product_2?.d || [];

  // Build quick lookup by QuestionTitle
  const byTitleMain = toIndexByTitle(dataMain);
  const byTitleOne = toIndexByTitle(dataOne);
  const byTitleTwo = toIndexByTitle(dataTwo);

  // Union of all question titles (keeps original casing)
  const allTitlesSet = new Set();
  for (const k of byTitleMain.keys()) allTitlesSet.add(k);
  for (const k of byTitleOne.keys()) allTitlesSet.add(k);
  for (const k of byTitleTwo.keys()) allTitlesSet.add(k);

  // If nothing to show, set a friendly message and exit
  if (allTitlesSet.size === 0) {
    const emptyHtml = `
      <div class="defaqto-compare-empty">
        No comparison data available.
      </div>`;
    ZT.setTransformData("defaqtoComparisonTableHtml", emptyHtml);

    // Also set the star block to a safe empty state
    ZT.setTransformData(
      "defaqtoStarRatingHtml",
      `<div class="defaqto-star-summary is-empty">No star rating data. <i class="fas fa-exclamation-triangle" style="color: rgb(255, 212, 59);"></i> No selections were made.</div>`
    );

    return;
  }

  // -------- Ordering Logic -------------------------------------------------

  // Priority titles in the exact order requested
  const priorityTitles = [
    "Private Car Insurance Star Rating",
    "NCD - Protection",
    "Repairs Guarantee Period",
    "Courtesy Car Guarantee",
    "Emergency 24 Hour Helpline",
    "Uninsured Driver Benefit",
    "New Car Damage",
    "Total Loss Courtesy Car",
    "Courtesy Car Period",
    "Accident Transport Location Options",
    "Car Rescue Cover",
    "Redelivery Costs",
    "Personal Accident - Death (standard)",
    "Personal Accident - Disability (standard)",
    "Personal Belongings",
    "Hotel Expenses - Maximum",
    "Theft of Keys (standard limit)",
    "Loss of Keys (standard limit)",
    "Cancellation Fee",
    "Courtesy Car Class",
    "Adjustment Fee",
    "Cooling Off Period Basis",
    "Foreign Use Annual Limit"
  ];

  // Build a lookup of actual titles (trim+lowercase -> original title)
  const titleLookup = new Map();
  for (const title of allTitlesSet) {
    const key = String(title).trim().toLowerCase();
    if (!titleLookup.has(key)) {
      titleLookup.set(key, title);
    }
  }

  const usedKeys = new Set();
  const orderedTitles = [];

  // 1) Add any titles that match the priority list, in that order
  for (const p of priorityTitles) {
    const key = String(p).trim().toLowerCase();
    const match = titleLookup.get(key);
    if (match) {
      orderedTitles.push(match);
      usedKeys.add(key);
    }
  }

  // 2) Collect remaining titles that are not in the priority list
  const remainingTitles = [];
  for (const [key, origTitle] of titleLookup.entries()) {
    if (!usedKeys.has(key)) {
      remainingTitles.push(origTitle);
    }
  }

  // 3) Sort remaining titles alphabetically
  remainingTitles.sort((a, b) =>
    String(a).localeCompare(String(b), undefined, { sensitivity: "base" })
  );

  // 4) Final ordered list (still includes star title for ordering)
  const finalTitlesAll = orderedTitles.concat(remainingTitles);

  // ✅ Enhancement: remove star title from table titles
  const finalTitlesForTable = finalTitlesAll.filter((t) => !isStarRatingTitle(t));

  // -------- Build HTML (TABLE) --------------------------------------------

  // Utility: cell content for a given column
  // extraClass is used so we can highlight the main product's "win" cells.
  const answerFor = (title, sourceIdx, showCol, extraClass = "") => {
    if (!showCol) return `<td class="is-missing" aria-hidden="true">—</td>`;
    const row = sourceIdx.get(title);
    const rawText = pullAnswer(row);

    const displayHtml = rawText ? enc(rawText) : "—";

    const missingClass = rawText ? "" : " is-empty";
    const cls = (missingClass + " " + extraClass).trim();
    return `<td class="${cls}">${displayHtml}</td>`;
  };

  // Header badges if a product id is missing
  const availabilityNote = (has) =>
    (has ? "" : ` <span class="col-badge">not selected</span>`);

  let html = `
  <div class="defaqto-compare-wrap">
    <table class="defaqto-compare" role="table">
      <thead>
        <tr>
          <th scope="col" class="col-questions">Questions</th>
          <th scope="col">${enc(productName)}${availabilityNote(colHasMain)}</th>
          <th scope="col">${enc(productOneName)}${availabilityNote(colHasOne)}</th>
          <th scope="col">${enc(productTwoName)}${availabilityNote(colHasTwo)}</th>
        </tr>
      </thead>
      <tbody>
  `;

  // Build rows in the final order (table list)
  finalTitlesForTable.forEach((title, index) => {
    const isKeyRow = index < 6; // first 6 rows stand out (after star row removed)
    const keyRowClass = isKeyRow ? " is-key-row" : "";

    // Determine if main product "wins" this row
    const rowMain = byTitleMain.get(title);
    const rowOne = byTitleOne.get(title);
    const rowTwo = byTitleTwo.get(title);

    const sigMain = imageSignal(rowMain?.DisplayImageUrl);
    const sigOne = imageSignal(rowOne?.DisplayImageUrl);
    const sigTwo = imageSignal(rowTwo?.DisplayImageUrl);

    // Condition:
    // - main product is "yes"
    // - and either comparator is "no" or "maybe" (when that comparator is present)
    const mainBeatsOne = colHasOne && (sigOne === "no" || sigOne === "maybe");
    const mainBeatsTwo = colHasTwo && (sigTwo === "no" || sigTwo === "maybe");

    const highlightMainCell =
      sigMain === "yes" && (mainBeatsOne || mainBeatsTwo);

    const mainExtraClass = highlightMainCell ? " is-main-advantage" : "";

    // ----- Build clickable help panel for this question -------------------
    const helpTextRaw = getHelpForRow(rowMain, rowOne, rowTwo);
    const helpText = helpTextRaw ? String(helpTextRaw) : "";
    let questionCellInner = "";

    // Icon first (only if we have help text)
    if (helpText) {
      // Preserve newlines from Help as <br>
      const helpHtml = enc(helpText).replace(/\r?\n/g, "<br>");

      questionCellInner += `
        <button type="button"
                class="question-help-trigger"
                aria-expanded="false"
                aria-label="More information about ${enc(title)}">
          <span class="question-help-icon">?</span>
        </button>
        <div class="question-help-panel" hidden>
          <div class="question-help-header">${enc(title)}</div>
          <div class="question-help-body">${helpHtml}</div>
          <button type="button" class="question-help-close">close</button>
        </div>
      `;
    }

    // Question text after the icon
    questionCellInner += `<span class="question-label">${enc(title)}</span>`;

    html += `
      <tr class="${keyRowClass}">
        <th scope="row" class="question">${questionCellInner}</th>
        ${answerFor(title, byTitleMain, colHasMain, mainExtraClass)}
        ${answerFor(title, byTitleOne, colHasOne)}
        ${answerFor(title, byTitleTwo, colHasTwo)}
      </tr>
    `;
  });

  html += `
      </tbody>
    </table>
  </div>`;

  // Expose for Content Node rendering
  let css = `<style>.defaqto-star-summary{border:none;border-radius:8px;padding:12px 14px;margin:0 auto 12px auto;background:#fff;max-width:980px;text-align:center}.defaqto-star-grid{display:inline-flex;align-items:center;justify-content:center;gap:0;flex-wrap:wrap}.defaqto-star-item{padding:0 16px;min-width:220px}.defaqto-star-item:not(:last-child){border-right:1px solid #e5e7eb}.defaqto-star-name{font-weight:500;font-size:13px;margin-bottom:6px;color:#333}.defaqto-compare .star-rating,.star-rating{display:inline-flex;align-items:center;white-space:nowrap;line-height:1;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif}.defaqto-compare .star-rating__star,.star-rating__star{font-size:1.7em;margin-right:1px;line-height:1;color:#ffc107!important}.defaqto-compare .star-rating__star.is-empty,.star-rating__star.is-empty{opacity:.35}.defaqto-compare .star-rating__number,.star-rating__number{margin-left:8px;font-size:1em;color:#333}@media (max-width:640px){.defaqto-star-item{min-width:auto;padding:10px 12px}.defaqto-star-item:not(:last-child){border-right:none;border-bottom:1px solid #e5e7eb}}.defaqto-compare th.question{display:flex;align-items:center;gap:6px;position:relative;overflow:visible;vertical-align:top}.question-label,.question-help-trigger{display:inline-flex;align-items:center}.question-help-trigger{flex-shrink:0;background:none;border:none;padding:0;margin-right:4px;cursor:pointer}.question-label{white-space:normal}.defaqto-compare th.question .question-label{display:inline-block;margin-left:4px}.question-help-icon{display:inline-block;width:16px;height:16px;line-height:14px;text-align:center;border-radius:50%;border:1px solid #29508c;color:#29508c;font-size:11px;font-weight:700;font-family:Arial,sans-serif;background-color:#fff}.question-help-panel{position:absolute;top:100%;right:0;margin-top:4px;max-width:380px;background-color:#fff;border:1px solid #29508c;box-shadow:0 2px 6px rgba(0,0,0,.2);padding:10px 12px;z-index:100;font-family:Arial,sans-serif;font-size:12px}.question-help-header{font-weight:700;margin-bottom:6px;color:#1c2753}.question-help-body{margin-bottom:8px;line-height:1.4}.question-help-close{background:none;border:none;padding:0;font-size:12px;color:#0000ee;cursor:pointer;text-decoration:underline}.zt-form-group{margin-bottom:12px}.defaqto-compare td.is-main-advantage{font-weight:700;color:#008000}.defaqto-compare-wrap{overflow-x:auto;-webkit-overflow-scrolling:touch}table.defaqto-compare{width:100%;border-collapse:separate;border-spacing:0;font-size:14px;line-height:1.3;border:1px solid #e5e7eb;border-radius:8px}.defaqto-compare thead th{position:sticky;top:0;background:#f8fafc;text-align:left;padding:12px 14px;font-weight:600;border-bottom:1px solid #e5e7eb;white-space:nowrap}.defaqto-compare thead th .col-badge{display:inline-block;margin-left:8px;font-size:11px;font-weight:600;text-transform:uppercase;background:#fee2e2;color:#991b1b;border:1px solid #fecaca;border-radius:999px;padding:2px 6px;vertical-align:middle}.defaqto-compare tbody th.question{background:#fcfcfd;font-weight:500;padding:10px 14px;border-bottom:1px solid #f1f5f9;min-width:220px}.defaqto-compare tbody td{padding:10px 14px;border-bottom:1px solid #f1f5f9;vertical-align:top}.defaqto-compare tbody tr:nth-child(2n) td,.defaqto-compare tbody tr:nth-child(2n) th.question{background:#fbfdff}.defaqto-compare td.is-empty,.defaqto-compare td.is-missing{color:#9ca3af;font-style:italic}@media (max-width:640px){.defaqto-compare thead th,.defaqto-compare tbody td,.defaqto-compare tbody th.question{padding:10px 12px}.defaqto-compare tbody th.question{min-width:180px}}.defaqto-compare tr.is-key-row{background-color:rgba(0,115,255,.12)}.defaqto-compare tr.is-key-row th,.defaqto-compare tr.is-key-row td{font-weight:600;border-bottom:2px solid rgba(0,115,255,.3)}.defaqto-compare tr.is-key-row th.question{border-left:4px solid rgba(0,115,255,.8);padding-left:.75em}</style>`
  ZT.setTransformData("defaqtoComparisonTableHtml", `${css}${html}`);

  // -------- Build HTML (STAR SUMMARY, NON-TABLE) ---------------------------

  const buildStarBlockItem = (label, showCol, sourceIdx) => {
    if (!showCol) return "";

    const row = sourceIdx.get(STAR_RATING_TITLE) || null;
    const rawText = pullAnswer(row);
    const starsHtml = renderStarRatingHtml(rawText);

    const ratingHtml = starsHtml
      ? starsHtml
      : (rawText
          ? `<span class="defaqto-star-value">${enc(rawText)}</span>`
          : `<span class="defaqto-star-value is-empty">—</span>`);

    return `
      <div class="defaqto-star-item">
        <div class="defaqto-star-name">${enc(label)}</div>
        <div class="defaqto-star-rating">${ratingHtml}</div>
      </div>
    `;
  };

  const starItems = [
    buildStarBlockItem(productName, colHasMain, byTitleMain),
    buildStarBlockItem(productOneName, colHasOne, byTitleOne),
    buildStarBlockItem(productTwoName, colHasTwo, byTitleTwo),
  ].filter(Boolean);

  const starBlockHtml = starItems.length
    ? `
      <div class="defaqto-star-summary" role="region">
        <div class="defaqto-star-grid">
          ${starItems.join("")}
        </div>
      </div>
    `
    : `<div class="defaqto-star-summary is-empty">No star rating data.</div>`;

  ZT.setTransformData("defaqtoStarRatingHtml", starBlockHtml);

})();

/**
 * PART 2: Defaqto → LLM-friendly JSON
 * (Your original block, unchanged)
 *
 * Builds a compact, self-describing JSON for the selected products
 * and stores it as:
 *   transformations.defaqtoComparisonJson  (pretty-printed string)
 *   transformations.defaqtoComparisonJsonObj (object)
 *
 * Columns included ONLY when the corresponding *_id variable has a value.
 */
(function () {
  // ---------- Utilities ----------
  const htmlStrip = (s) => String(s ?? "").replace(/<[^>]*>/g, " ").replace(/\s+/g, " ").trim();
  const trim = (v) => String(v ?? "").trim();

  const slugify = (s) =>
    trim(s)
      .toLowerCase()
      .replace(/&/g, " and ")
      .replace(/[^a-z0-9]+/g, "_")
      .replace(/^_+|_+$/g, "")
      .replace(/_{2,}/g, "_");

  // Choose best display text (priority: AltText → DisplayText → BrochureText)
  const chooseAnswerText = (row) => {
    if (!row) return "";
    const a = trim(row.AltText);
    if (a) return a;
    const d = trim(row.DisplayText);
    if (d) return d;
    const b = htmlStrip(row.BrochureText);
    if (b) return b;
    return "";
  };

  // Extract machine-friendly signals from row
  const imageSignal = (url) => {
    const u = trim(url).toLowerCase();
    if (!u) return null;
    if (u.includes("/yes")) return "meets";
    if (u.includes("/no")) return "does_not_meet";
    if (u.includes("/maybe")) return "optional_or_partial";
    if (u.includes("/off")) return "not_applicable";
    return null;
  };

  // Parsers return {type, value, unit, boolean, enum, confidence}
  const parseValue = (text) => {
    const raw = trim(text);
    if (!raw) return { type: "empty", value: null, unit: null, boolean: null, enum: null, confidence: 0.0 };

    // Booleans
    const t = raw.toLowerCase();
    if (["yes", "true", "included", "guaranteed"].includes(t)) {
      return { type: "boolean", value: 1, unit: null, boolean: true, enum: null, confidence: 0.95 };
    }
    if (["no", "false", "not included", "excluded"].includes(t)) {
      return { type: "boolean", value: 0, unit: null, boolean: false, enum: null, confidence: 0.95 };
    }
    if (["optional", "maybe"].includes(t)) {
      return { type: "enum", value: null, unit: null, boolean: null, enum: "optional", confidence: 0.85 };
    }

    // Currency (GBP-style; keeps integer part only if needed)
    // Examples: "£1,500", "£0", "£200 or more"
    const money = raw.match(/£\s*([0-9]{1,3}(?:,[0-9]{3})*|\d+)(?:\.\d+)?/);
    if (money) {
      const num = Number(money[1].replace(/,/g, ""));
      return { type: "currency", value: isNaN(num) ? null : num, unit: "GBP", boolean: null, enum: null, confidence: 0.9 };
    }

    // Percent e.g., "59%", "Less than 60%"
    const pct = raw.match(/(\d+(?:\.\d+)?)\s*%/);
    if (pct) {
      return { type: "percent", value: Number(pct[1]), unit: "percent", boolean: null, enum: null, confidence: 0.9 };
    }

    // Duration: years/days (simple cases)
    const years = raw.match(/(\d+)\s*years?/i);
    if (years) {
      return { type: "duration", value: Number(years[1]), unit: "years", boolean: null, enum: null, confidence: 0.85 };
    }
    const days = raw.match(/(\d+)\s*days?/i);
    if (days) {
      return { type: "duration", value: Number(days[1]), unit: "days", boolean: null, enum: null, confidence: 0.85 };
    }

    // Classifications / enums (some common textual buckets)
    // Add light normalization for frequently seen values
    const enumMap = {
      "standard": "standard",
      "service": "service",
      "small hatchback": "small_hatchback",
      "pro-rata": "pro_rata",
      "during repair": "during_repair",
      "safe place": "safe_place",
      "guaranteed": "guaranteed",
      "ncd,excess": "ncd_and_excess",
    };
    if (enumMap[t]) {
      return { type: "enum", value: null, unit: null, boolean: null, enum: enumMap[t], confidence: 0.8 };
    }

    // Fallback: opaque string
    return { type: "string", value: raw, unit: null, boolean: null, enum: null, confidence: 0.6 };
  };

  const getVar = (name, fallback = null) => {
    try {
      const v = (typeof globalThis[name] !== "undefined") ? globalThis[name] : undefined;
      if (v === undefined || v === null) return fallback;
      const s = String(v);
      return s.trim() === "" ? fallback : s;
    } catch {
      return fallback;
    }
  };

  // ---------- Product selections ----------
  const product_id = getVar("product_id", null);
  const product_one_id = getVar("product_one_id", null);
  const product_two_id = getVar("product_two_id", null);

  const product_name = getVar("product_name", "Product");
  const product_one_name = getVar("product_one_name", "Product 1");
  const product_two_name = getVar("product_two_name", "Product 2");

  // ---------- Data sources ----------
  const dataMain = (globalThis.actions?.defaqto_loadanswersbyquestionids?.d) || [];
  const dataOne = (globalThis.actions?.defaqto_loadanswersbyquestionids_product_1?.d) || [];
  const dataTwo = (globalThis.actions?.defaqto_loadanswersbyquestionids_product_2?.d) || [];

  const indexByTitle = (rows) => {
    const m = new Map();
    (rows || []).forEach(r => {
      const t = r?.QuestionTitle ? r.QuestionTitle.trim() : null;
      if (t && !m.has(t)) m.set(t, r);
    });
    return m;
  };

  const iMain = indexByTitle(dataMain);
  const iOne = indexByTitle(dataOne);
  const iTwo = indexByTitle(dataTwo);

  // Titles union
  const titles = new Set();
  for (const k of iMain.keys()) titles.add(k);
  for (const k of iOne.keys()) titles.add(k);
  for (const k of iTwo.keys()) titles.add(k);
  const sorted = Array.from(titles).sort((a, b) => a.localeCompare(b, undefined, { sensitivity: "base" }));

  // Active columns = only with IDs provided
  const cols = [];
  if (product_id) cols.push({ key: "main", id: product_id, name: product_name, idx: iMain });
  if (product_one_id) cols.push({ key: "product_1", id: product_one_id, name: product_one_name, idx: iOne });
  if (product_two_id) cols.push({ key: "product_2", id: product_two_id, name: product_two_name, idx: iTwo });

  // If no questions, emit empty shell
  if (sorted.length === 0) {
    const emptyOut = {
      schema_version: "1.0.0",
      meta: { generated_at: new Date().toISOString(), products: [] },
      questions_by_id: {}
    };
    ZT.setTransformData("defaqtoComparisonJson", JSON.stringify(emptyOut, null, 2));
    ZT.setTransformData("defaqtoComparisonJsonObj", emptyOut);
    return;
  }

  // ---------- Build LLM-friendly payload ----------
  const questions_by_id = {};
  for (const title of sorted) {
    const q_id = slugify(title);

    const perProduct = {};
    cols.forEach(c => {
      const row = c.idx.get(title) || null;
      const bestText = chooseAnswerText(row);
      const parsed = parseValue(bestText);
      const signal = imageSignal(row?.DisplayImageUrl);

      perProduct[c.key] = {
        answer_text: bestText || "",
        normalized: parsed, // {type, value, unit, boolean, enum, confidence}
        signals: {
          meets_requirement: signal, // meets | does_not_meet | optional_or_partial | not_applicable | null
          hurdle_text: trim(row?.HurdleText) || null
        },
        provenance: {
          question_id: (row?.QuestionId ?? null),
          table_column_id: (row?.TableColumnId ?? null),
          brochure_text_excerpt: htmlStrip(row?.BrochureText || "").slice(0, 280) || null,
          display_image_url: trim(row?.DisplayImageUrl) || null
        }
      };
    });

    questions_by_id[q_id] = {
      title,
      answers_by_product: perProduct
    };
  }

  const output = {
    schema_version: "1.0.0",
    meta: {
      generated_at: new Date().toISOString(),
      products: cols.map(c => ({ key: c.key, id: c.id, name: c.name }))
    },
    questions_by_id
  };

  ZT.setTransformData("defaqtoComparisonJson", JSON.stringify(output, null, 2));
  ZT.setTransformData("defaqtoComparisonJsonObj", output);
  ZT.log("Output for LLM: " + JSON.stringify(output));
  ZT.log(`[Defaqto LLM JSON] Questions: ${Object.keys(questions_by_id).length}; Products: ${output.meta.products.length}`);
})();

