// Node 12 - Validate Product Selection
// Inputs : form data product_id, product_one_id, product_two_id
//          (captured natively from the node 1 <select class="zt-data"> fields)
//          actions.defaqto_loadproductdropdownlist_product / _product_1 / _product_2
// Outputs: form data is_product_selection_valid (boolean)
//          form data product_name / product_one_name / product_two_name
//          form data product_provider_id / product_one_provider_id / product_two_provider_id
// Rule   : valid only when the First Central product AND at least one comparison product are selected.

function g(k) { return String(ZT.getVariableValue(k, "") || "").trim(); }

function findProduct(list, id) {
  if (!id || !Array.isArray(list)) return null;
  return list.find(p => String(p.ProductID) === id) || null;
}

const SLOTS = [
  { idVar: "product_id",     nameVar: "product_name",     provVar: "product_provider_id",     list: actions?.defaqto_loadproductdropdownlist_product?.d?.ProductDisplayList },
  { idVar: "product_one_id", nameVar: "product_one_name", provVar: "product_one_provider_id", list: actions?.defaqto_loadproductdropdownlist_product_1?.d?.ProductDisplayList },
  { idVar: "product_two_id", nameVar: "product_two_name", provVar: "product_two_provider_id", list: actions?.defaqto_loadproductdropdownlist_product_2?.d?.ProductDisplayList }
];

SLOTS.forEach(slot => {
  const id = g(slot.idVar);
  const product = findProduct(slot.list, id);
  ZT.setFormData(slot.idVar, id);
  ZT.setFormData(slot.nameVar, product ? String(product.DisplayName || "") : "");
  ZT.setFormData(slot.provVar, product ? String(product.ProviderID ?? "") : "");
});

const hasMain = g("product_id") !== "";
const hasComparison = g("product_one_id") !== "" || g("product_two_id") !== "";

ZT.setFormData("is_product_selection_valid", hasMain && hasComparison);
